H=[['拉丁语 mīrus → mīrārī','令人惊奇的 → 惊叹、注目']]
MIRROR=H+[['古法语 mirer → mireor；中古英语 mirour','看 → 供人照看的镜子'],['英语 mirror','镜子；照出、反映']]
MARVEL=H+[['拉丁 mīrābilis / mīrābilia → 古法语 merveille','奇妙的／奇妙之物 → 令人惊叹的事物'],['中古英语 merveile → marvel','奇观；惊叹']]
MIRACLE=H+[['拉丁 mīrāculum → 古法语 miracle','令人惊叹之物；奇迹'],['中古英语 → 英语 miracle','奇迹；意外的好结果']]
ADMIRE=H+[['拉丁 ad- + mīrārī → admīrārī','对某事惊叹'],['法语 admirer／拉丁语借入 → 英语 admire','惊叹 → 欣赏、钦佩']]
ADMIRABLE=H+[['拉丁 admīrārī → admīrābilis；法语 admirable','令人惊叹、值得赞赏的'],['英语 admirable','值得钦佩的']]
MIRACULOUS=H+[['拉丁 mīrāculum → mīrāculōsus；法语 miraculeux','奇迹 → 如奇迹一般的'],['英语 miraculous','奇迹般的；不可思议的']]
def D(h,label,meaning):return h+[[label,meaning]]
W=[
E('mirror','英 /ˈmɪrə/；美 /ˈmɪrər/','镜子；映出；反映','镜子把你面前的样子送回眼前；说一份报告 mirrors reality，就是报告照出了实际情况。','从法语“看”的词族借来；不是英语 mir + ror。动词来自名词。',MIRROR,'早期“惊叹、注目”这条线发展出“观看”，再产生供人照看的镜子。今天的动词也可说两件事十分相像。','look in a mirror；mirror an experience；a mirror image。','reflect 可说反光、反映，也可说思考；mirror 作动词通常着重照出或对应。',('She checked her hair in the mirror.','她对着镜子检查头发。'),('The novel mirrors the tensions in a small town.','这部小说反映了一个小镇里的矛盾。'),sources=['https://www.etymonline.com/word/mirror']),
E('marvel','英 /ˈmɑːvəl/；美 /ˈmɑːrvəl/','惊叹；令人惊叹的事物','看到一座悬在深谷上的桥，心里冒出“这也造得出来！”——这个反应就是 marvel。','法语 merveille 的借词，远接拉丁 mīrābilia“奇妙之物”；现代不再按字母拆。',MARVEL,'名词把镜头放在那件非凡的东西上，动词把镜头放在看者的惊叹上。','marvel at；an engineering marvel。','marvel 不要求超自然原因；miracle 有时有宗教上的神迹义。',('We marvelled at the tiny details in the carving.','我们惊叹于雕刻中那些细小的细节。'),('The bridge is an engineering marvel.','这座桥是一个工程奇观。'),sources=['https://www.etymonline.com/word/marvel']),
E('miracle','英 /ˈmɪrəkəl/；美 /ˈmɪrəkəl/','奇迹；令人难以置信的好结果','原以为肯定赶不上，最后一分钟居然赶上了，你会感叹“It’s a miracle!”。','拉丁 mīrāculum 经法语传入；-culum 是古代名词构形成分，不把现代 miracle 硬拆成英语小词。',MIRACLE,'本来指令人惊叹的事；宗教中可指神迹，日常也用来夸张地说“这结果太难得了”。','a miracle；by a miracle；work miracles。','luck 只说运气好；miracle 把难以置信的程度拉得很高。日常感叹不一定是在作宗教断言。',('It was a miracle that we found the ring in the snow.','我们竟在雪里找到了戒指，简直是奇迹。'),('A fresh coat of paint can work miracles in a small room.','小房间重新刷一遍漆，往往会有惊人的改观。'),sources=['https://www.etymonline.com/word/miracle']),
E('admire','英 /ədˈmaɪə/；美 /ədˈmaɪr/','欣赏；钦佩','看着一个人顶住压力仍坚持原则，你心里会说“真了不起”。这就是 admire。','历史上 ad-“朝向、对于”+ mīrārī“惊叹”；经法语或拉丁语借入。',ADMIRE,'原来偏“看得惊叹”，后来常带肯定和尊重。也能单纯欣赏风景、衣服，不必都是人格崇拜。','admire someone for；admire the view。','admire 是欣赏钦佩；envy 是羡慕对方拥有的东西，可能也带嫉妒。',('I admire her for speaking honestly.','我钦佩她坦诚说话。'),('We stopped to admire the view.','我们停下来欣赏景色。'),sources=['https://www.etymonline.com/word/admire']),
E('Miranda','/mɪˈrændə/','米兰达〔人名；也为天卫五名称〕','这个名字背后是“值得惊叹的人”。先把它当名字认，不要把遇到的每个 Miranda 都翻成“奇迹”。','《暴风雨》角色名来自拉丁 mirandus 的阴性形式 miranda“值得惊叹的”；同形姓氏有独立命名历史。',[H[0],['拉丁 miranda → 莎士比亚角色 Miranda','值得惊叹的 → 女性角色名'],['英语人名；卫星 Miranda','人名；天卫五取名自该角色']],'英语中首字母大写。天卫五的名称接的是文学角色；姓氏及法律搭配另有各自背景，不从这个角色一路推导。','Miranda in The Tempest；the moon Miranda。','Miranda 是专名，miracle 是普通名词。名字的词源不能当成对这个人的实际评价。',('Miranda is a character in The Tempest.','米兰达是《暴风雨》中的一个角色。'),('The students studied images of Miranda, a moon of Uranus.','学生们研究了天王星卫星天卫五的图像。'),sources=['https://en.wiktionary.org/wiki/Miranda#English','https://science.nasa.gov/uranus/moons/miranda/']),
E('admiration','/ˌædməˈreɪʃən/','钦佩；赞赏','admire 是你心里“佩服他”的动作，admiration 是这份佩服之情。','来自法语 admiration 或拉丁 admīrātiō；现代可联系 admire 与名词后缀 -ation，但不是英语 admire 之后才凭空造出。',[H[0],['拉丁 admīrārī → admīrātiō；法语 admiration','惊叹、钦佩 → 这种感情'],['英语 admiration','赞赏、钦佩']],'通常不可数，常说 admiration for somebody。可以很敬重一个人，却不一定喜欢他的所有决定。','have admiration for；in admiration；win admiration。','admiration 是赞赏之情；adoration 常更热烈，接近爱慕或崇拜。',('She watched the dancers with admiration.','她怀着赞赏看着舞者们。'),('His patience won the admiration of the team.','他的耐心赢得了团队的钦佩。'),sources=['https://www.etymonline.com/word/admiration']),
E('marvelous','英 /ˈmɑːvələs/；美 /ˈmɑːrvələs/','极好的；令人惊叹的','收到一顿意外丰盛的晚餐，你说 marvelous，就是“太棒了”。','来自古法语 merveillus，现代可联系 marvel + -ous；英式常拼 marvellous。',[H[0],['古法语 merveille → merveillus','奇妙之物 → 奇妙的'],['中古英语 merveilous → marvelous / marvellous','令人惊叹的；极好的']],'现在常是热情称赞，程度可以很日常；不要求真的发生不可解释的事。','a marvelous idea；have a marvelous time。','marvelous 是强烈赞美；miraculous 更突出结果像奇迹、原本很难发生。',('That is a marvelous idea.','那是个极好的主意。'),('We had a marvelous time by the sea.','我们在海边度过了一段美好的时光。'),sources=['https://www.etymonline.com/word/marvelous']),
E('admirable','英 /ˈædmərəbəl/；美 /ˈædmərəbəl/','值得钦佩的','遇到难题不推责，而是认真补救，这种态度本身值得你竖大拇指。','借自法语 admirable 或拉丁 admīrābilis。可用 admire + -able 帮助理解，但历史形成在借入之前。',ADMIRABLE,'它评价品质或表现“值得赞赏”，不是“能够欣赏”。重音在开头，不能照搬 admire 的重音。','admirable courage；an admirable effort。','admirable 说值得赞赏；admiring 说看者带着赞赏。an admiring glance 是赞赏的目光。',('She showed admirable patience with the new students.','她对新生表现出令人钦佩的耐心。'),('Your attempt to fix the problem was admirable.','你努力解决问题，这一点值得赞赏。'),sources=['https://www.etymonline.com/word/admirable']),
E('miraculous','英 /mɪˈrækjələs/；美 /məˈrækjələs/','奇迹般的；不可思议的','所有人都以为丢失的小狗回不来了，它却自己找到了家——这个结果可以叫 miraculous。','从法语 miraculeux 借来，远接拉丁 mīrāculum“奇迹”；现代可联系 miracle，但历史上已有形容词形式。',MIRACULOUS,'既可用于宗教神迹，也可夸张形容极难发生的好结果。看到这个词不能自动认定事件违反自然规律。','a miraculous escape；a miraculous recovery。','amazing 只是很惊人；miraculous 更像“照理说几乎不可能，居然成了”。',('The trapped hikers made a miraculous escape.','被困的徒步者奇迹般地脱险了。'),('Finding the lost notebook felt miraculous.','找到那本丢失的笔记本，感觉像发生了奇迹。'),sources=['https://www.etymonline.com/word/miraculous']),
E('mirrored','英 /ˈmɪrəd/；美 /ˈmɪrərd/','装有镜面的；被映出的；相对应的','衣柜门上整面都是镜子，可以说 mirrored doors；某人的动作被另一人照着做，也能用 mirrored。','mirror + -ed；可作动词过去式、过去分词，也可作“装有镜面”的形容词。',D(MIRROR,'英语 mirror → mirrored','镜子／照出 → 有镜面的／映出的'),'镜面义说物体表面；过去式则说发生了映照或模仿。看它在句中修饰名词还是充当谓语。','mirrored walls；mirrored sunglasses；be mirrored in。','mirrored 说有镜面或映照关系；shiny 只是发亮，不一定能形成清楚的像。',('The mirrored doors made the room look larger.','镜面门让房间显得更大。'),('His disappointment was mirrored in her expression.','他的失望也反映在她的表情里。')),
E('mirage','英 /ˈmɪrɑːʒ/；美 /məˈrɑːʒ/','海市蜃楼；看似可得的幻象','炎热路面前方像铺着水，走近却没有：眼睛看见了影像，那个位置却没有想象中的水。','直接借法语 mirage，通常联系 se mirer“映现”、拉丁 mirari 词族；不是英语 mirror + age。',[H[0],['法语 se mirer → mirage','映现 → 折射形成的虚像'],['英语 mirage','海市蜃楼；虚幻的希望']],'真实现象由光线在不同密度的空气层中折射形成；比喻义说某种好处看着就在前方，实际抓不住。','a desert mirage；prove to be a mirage。','illusion 是各种错觉、幻象的总称；mirage 原本特指大气折射形成的影像。',('A mirage made the road look wet.','海市蜃楼般的虚像让路面看起来湿漉漉的。'),('The promise of easy success turned out to be a mirage.','轻松成功的承诺最终只是幻象。'),sources=['https://www.etymonline.com/word/mirage']),
E('admirer','英 /ədˈmaɪərə/；美 /ədˈmaɪrər/','仰慕者；欣赏者；追求者','常看某位画家的作品、赞赏他的才华，你就是他的 admirer；偷偷送花的人也可能是 admirer。','admire + -er，去词尾 e，再加表示人的 -er。',D(ADMIRE,'英语 admire → admirer','欣赏、钦佩 → 怀有这种感情的人'),'对艺术家、作品常是欣赏；说 a secret admirer 往往有爱慕意味。不能把所有 admirer 都译成恋爱追求者。','an admirer of；a secret admirer；a longtime admirer。','fan 常强调爱好者身份；admirer 更强调赞赏，也可能带爱慕。',('I have always been an admirer of her writing.','我一直很欣赏她的文字。'),('The flowers came from a secret admirer.','这些花是一位匿名爱慕者送来的。')),
E('miraculously','英 /mɪˈrækjələsli/；美 /məˈrækjələsli/','奇迹般地；不可思议地','本以为文件彻底丢了，最后竟然恢复了。miraculously 给这件事加上“居然还成功了”的惊讶。','miraculous + -ly，形容词变副词。',D(MIRACULOUS,'英语 miraculous → miraculously','奇迹般的 → 以令人难以置信的方式发生'),'常放句首，评论整个结果；也可修饰 survive、recover、reappear 等动词。','miraculously survive；miraculously intact。','fortunately 只说结果幸运；miraculously 还强调原本极难想象。',('Miraculously, no one was hurt when the roof fell.','屋顶塌下来时，竟然奇迹般地无人受伤。'),('The missing page miraculously reappeared in my bag.','那张丢失的纸竟又神奇地出现在我的包里。')),
E('admirably','英 /ˈædmərəbli/；美 /ˈædmərəbli/','令人钦佩地；出色地','突发状况来了，她处理得沉稳妥当；admirably 评价的是她把事情做得很值得赞赏。','admirable 的 -le 变为 -ly，形成副词；不是在 admirable 后直接再添完整 -ly。',D(ADMIRABLE,'英语 admirable → admirably','值得钦佩的 → 做得值得钦佩'),'常修饰表现、应对或完成任务，也可说 admirably clear“清楚得很好”。','cope admirably；perform admirably；admirably suited。','admiringly 是带着钦佩地看别人；admirably 是自己做得值得别人钦佩。',('She coped admirably with the sudden change.','她出色地应对了突如其来的变化。'),('The instructions were admirably clear.','这些说明写得十分清楚。')),
E('mirrorless','英 /ˈmɪrələs/；美 /ˈmɪrərləs/','无镜面的；无反相机的','这里的 -less 就是“没有”。相机里的 mirrorless，特别指没有单反那套反光镜结构。','mirror + -less，英语否定形容词；摄影中也可省略 camera，作名词使用。',D(MIRROR,'英语 mirror + -less → mirrorless','镜子 → 没有反光镜的'),'无反相机的名称说的是内部取景结构，不是说镜头里完全没有玻璃，也不保证每款机身都更小。','a mirrorless camera；a mirrorless system。','mirrorless 与 DSLR 区分取景结构；digital 区分数码记录方式，无反本身也是数码相机。',('She packed a mirrorless camera for the trip.','她为旅行带上了一台无反相机。'),('The review compares a mirrorless model with a DSLR.','这篇评测比较了一款无反相机和一款数码单反。'),sources=['https://en.wiktionary.org/wiki/mirrorless#English','https://www.nikonusa.com/c/cameras/mirrorless-cameras/overview']),
E('marvelling','英 /ˈmɑːvəlɪŋ/；美 /ˈmɑːrvəlɪŋ/','正在惊叹；惊叹这一行为','大家围着微型城堡，越看细节越赞叹；marvelling 把这个正在发生的反应展现出来。','marvel + -ing；英式通常双写 l，美国英语常写 marveling。',D(MARVEL,'英语 marvel → marvelling / marveling','惊叹 → 正在惊叹或惊叹这一行为'),'通常是动词的 -ing 形式，接 at。名词用法也存在，但日常重点掌握 was marvelling at。','stand marvelling at；keep marvelling at。','marvelling 是人的反应；marvellous / marvelous 是对事物“好得惊人”的评价。',('We stood marvelling at the handmade model.','我们站着，对那个手工模型赞叹不已。'),('She kept marvelling at how quickly the garden had changed.','她一直惊叹花园变化得如此之快。')),
E('admirability','/ˌædmərəˈbɪləti/','值得钦佩这一特质〔少用〕','不是问“有多少人佩服他”，而是问“他的做法有什么值得佩服的地方”。','源于拉丁 admīrābilitās；现代可分析为 admirable 的 -ity 名词形式，-able 对应 -ability。',[H[0],['拉丁 admīrābilis → admīrābilitās','值得钦佩的 → 这种性质'],['英语 admirability','值得钦佩的性质']],'多见于书面讨论、伦理或人物评价。日常通常直接说 admirable，不必强用这个抽象名词。','the admirability of an action；question its admirability。','admiration 是观察者的感情；admirability 是被评价者值得赞赏的性质。',('The essay examines the admirability of his decision.','这篇文章讨论他的决定有何值得钦佩之处。'),('The admirability of the goal did not excuse the dishonest method.','目标值得赞赏，也不能为不诚实的手段开脱。'),sources=['https://en.wiktionary.org/wiki/admirability#English']),
E('admirative','/ədˈmaɪrətɪv/，也 /ˈædməreɪtɪv/','赞赏的；惊异语式的〔语言学〕','普通用法是眼里带着欣赏；语言学用法则抓“原来竟然这样”的意外感，并不一定是在夸人。','经法语 admiratif 或直接从中世纪拉丁 admirativus 借入，属于 admire 的历史词族。',[H[0],['拉丁 admīrārī → 中世纪拉丁 admirativus；法语 admiratif','惊叹 → 表示惊叹、赞赏的'],['英语 admirative','赞赏的；特定语言中的语式术语']],'日常形容眼神用 admiring 更自然。语法书里的 admirative 具体可兼有惊讶、转述等功能，要看该语言的分析。','an admirative tone；an admirative form。','admirative 语法术语与 mirative 有重叠，不能把不同语言的形式当成完全相同的一套规则。',('Her letter has an openly admirative tone.','她的信明显带着赞赏的语气。'),('The grammar describes an admirative form of the verb.','这本语法书描述了该动词的一种惊异语式形式。'),sources=['https://en.wiktionary.org/wiki/admirative#English','https://doi.org/10.1515/lity.1997.1.1.33']),
E('mirative','/ˈmɪrətɪv/','表示新知或意外的〔语言学〕；惊异范畴形式','想象你进门才发现屋里全是客人，脱口而出“原来你们都来了！”mirative 抓的是刚发现、出乎预料这一层。','这个语言学术语与 admirative 及拉丁 mīrārī“惊叹”词族有关；其具体形成有不同说明，不硬定为单一路径。',[H[0],['术语 admirative 与 mirative','把惊叹、新获信息纳入语法描述；名称形成细节有不同说明'],['语言学英语 mirative','表达信息新近、意外等意义的形式或范畴']],'有些语言会用专门形式标记这层意义。英语中也能用语气和句式表达意外，但不等于普通英语有同样的专门词尾。','a mirative marker；a mirative reading。','evidential 关心消息从哪里来；mirative 关心它对说话人是否新鲜、意外，两者可能交叉。',('The suffix has a mirative use in this example.','这个后缀在此例中有表达新知或意外的用法。'),('The researcher distinguishes mirative meaning from reported information.','研究者把惊异意义与转述的信息区分开。'),sources=['https://en.wiktionary.org/wiki/mirative#English','https://doi.org/10.1515/lity.1997.1.1.33','https://www.sciencedirect.com/science/article/pii/S0378216601800011']),
E('mirativity','/ˌmɪrəˈtɪvəti/〔按 mirative + -ity 构词读音〕','惊异性；对新知或意外的表达〔语言学〕','mirative 可以指某个具体标记，mirativity 则把镜头拉远：一门语言怎样表达“我刚知道，没想到”。','mirative + -ity；去词尾 e，变成表示性质或范畴的名词。',[H[0],['语言学术语 mirative → mirativity','表示新知、意外的 → 对这一意义领域的命名']],'研究中会区分语义上的意外感与固定语法范畴；不能见到感叹号，就断定该语言有专门的惊异语式。','the expression of mirativity；mirativity and evidentiality。','surprise 是日常情绪；mirativity 是语言如何表达相关信息状态的研究术语。',('Her paper studies the expression of mirativity in conversation.','她的论文研究会话中惊异性的表达。'),('The chapter discusses the relationship between mirativity and evidentiality.','这一章讨论惊异性与传信范畴的关系。'),sources=['https://en.wiktionary.org/wiki/mirativity#English','https://doi.org/10.1515/lity.1997.1.1.33']),
]
ROOT=dict(id='C0747',meaning='惊叹、注目；看得入神',core='MIR = WONDER',image='先想象一个人睁大眼睛：“真没想到！”往赞赏走，是 admire；往非凡的事走，是 miracle、marvel；“注目看”这条支线，则通到 mirror、mirage。',intro='这一组来自拉丁 mīrus“令人惊奇的”和 mīrārī“惊叹、注目”。核心不是单纯“看”，而是某件事把注意力牢牢吸住。经法语传下来的词，有些保留惊叹，有些转向观看、映现。',forms='拉丁 mīrārī 常以词典第一人称 mīror 列出，两者属于同一个动词。ad- 加在前面形成 admīrārī；mīrābilia 经法语变成 marvel 的前身。mirror、mirage、miracle 不是彼此加后缀形成，而是各自的历史支线。admirable 的重音在开头，admire 在后面。',branches=[['赞赏一个人或表现','admire, admiration, admirable'],['对非凡结果感到惊奇','marvel, miracle, miraculous'],['观看与映现','mirror, mirage'],['语言怎样标记意外','mirative, mirativity']],contrasts='admire 是欣赏或钦佩；marvel at 是惊叹某事；miracle 是被称为奇迹的事件。mirror 的历史虽同族，现在重点是映照。mirage 有真实的光学机制，不能因为人会看错，就说它是超自然奇迹。',practice='I admire the engineers and marvel at their work. Their bridge is an engineering marvel.\n\n我钦佩这些工程师，也惊叹他们的作品。他们造的桥是工程奇观。这里 admire 评价人，marvel at 表示反应，a marvel 指那件作品。',words=[w['word'] for w in W])
